<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\OfferStatus;
use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * A price offer on a listing. `proposer_id` made it and `recipient_id` must answer it:
 * buyer → seller for normal offers; a seller counter creates a child offer seller → buyer.
 */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $listing_id
 * @property string $buyer_id
 * @property string $seller_id
 * @property string $proposer_id
 * @property string $recipient_id
 * @property string|null $parent_offer_id
 * @property int $amount
 * @property string $currency
 * @property int|null $counter_amount
 * @property string|null $size
 * @property string|null $message
 * @property OfferStatus $status
 * @property Carbon $expires_at
 * @property Carbon|null $responded_at
 * @property Carbon|null $recipient_read_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Offer extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'off';

    protected $fillable = [
        'listing_id', 'buyer_id', 'seller_id', 'proposer_id', 'recipient_id', 'parent_offer_id', 'amount', 'currency',
        'counter_amount', 'size', 'message', 'status', 'expires_at', 'responded_at', 'recipient_read_at',
    ];

    protected function casts(): array
    {
        return [
            'status' => OfferStatus::class,
            'amount' => 'integer',
            'counter_amount' => 'integer',
            'expires_at' => 'datetime',
            'responded_at' => 'datetime',
            'recipient_read_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<Listing, $this> */
    public function listing(): BelongsTo
    {
        return $this->belongsTo(Listing::class)->withTrashed();
    }

    /** @return BelongsTo<User, $this> */
    public function buyer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'buyer_id');
    }

    /** @return BelongsTo<User, $this> */
    public function seller(): BelongsTo
    {
        return $this->belongsTo(User::class, 'seller_id');
    }

    /** @return BelongsTo<User, $this> */
    public function proposer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'proposer_id');
    }

    /** @return BelongsTo<User, $this> */
    public function recipient(): BelongsTo
    {
        return $this->belongsTo(User::class, 'recipient_id');
    }

    /** @return BelongsTo<Offer, $this> */
    public function parent(): BelongsTo
    {
        return $this->belongsTo(self::class, 'parent_offer_id');
    }

    /** @return HasMany<OfferEvent, $this> */
    public function events(): HasMany
    {
        return $this->hasMany(OfferEvent::class)->orderByDesc('occurred_at');
    }

    public function money(): Money
    {
        return Money::of($this->amount, $this->currency);
    }

    public function counterMoney(): ?Money
    {
        return Money::nullable($this->counter_amount, $this->currency);
    }

    public function isCounterOffer(): bool
    {
        return $this->proposer_id === $this->seller_id;
    }

    public function isParty(User $user): bool
    {
        return $user->id === $this->buyer_id || $user->id === $this->seller_id;
    }
}
